def eval_with_precedence(expr):
    # Evaluate expression with standard precedence: * / before + -
    tokens = expr.split()
    nums = []
    ops = []
    for t in tokens:
        if t in '+-*/':
            ops.append(t)
        else:
            nums.append(int(t))
    # First pass: resolve * and /
    new_nums = [nums[0]]
    new_ops = []
    for i, op in enumerate(ops):
        if op in ('*', '/'):
            prev = new_nums.pop()
            if op == '*':
                new_nums.append(prev * nums[i + 1])
            else:
                new_nums.append(prev // nums[i + 1])
        else:
            new_nums.append(nums[i + 1])
            new_ops.append(op)
    # Second pass: resolve + and -
    result = new_nums[0]
    for i, op in enumerate(new_ops):
        if op == '+':
            result += new_nums[i + 1]
        else:
            result -= new_nums[i + 1]
    return result

