    return f'[{ts}] {sym} [{source}] {message}'

class SimplePool:
    def __init__(self, factory, max_size):
        self.factory = factory
        self.max_size = max_size
        self.available = []
        self.total_created = 0

    def acquire(self):
        if self.available:
            return self.available.pop()
        if self.total_created < self.max_size:
            self.total_created += 1
            return self.factory()
        raise RuntimeError('pool exhausted')

    def release(self, conn):
        self.available.append(conn)

class TrackedPool(SimplePool):
    def __init__(self, factory, max_size):
        super().__init__(factory, max_size)
        self.in_use = set()

    def acquire(self):
        conn = super().acquire()
        self.in_use.add(id(conn))
        return conn

    def release(self, conn):
        self.in_use.discard(id(conn))
        super().release(conn)

